  'values.v1i3': 'ಪ್ರೊಪ್ರೈಟರಿ ಫಾರ್ಮ್ಯಾಟ್ ಅಥವಾ ಪ್ರೋಟೋಕಾಲ್‌ಗಳಿಲ್ಲ',
  'values.v2t': 'ಕಮ್ಯೂನಿಟಿಯೇ ಮೊದಲು',
  'values.v2d':
    'ಬಹಿರಂಗವಾಗಿ ನಿರ್ಮಿಸಲಾಗುತ್ತಿದೆ. ಟ್ರೇಡರ್‌ಗಳೊಂದಿಗೆ ಅಭಿವೃದ್ಧಿಪಡಿಸಲಾಗುತ್ತಿದೆ. ಪ್ರತಿ ಫೀಚರ್ ರಿಕ್ವೆಸ್ಟ್ ಕೂಡ ಮುಖ್ಯ. ಅಲ್ಗೋ ಟ್ರೇಡಿಂಗ್‌ನ ಭವಿಷ್ಯವನ್ನು ರೂಪಿಸುತ್ತಿರುವ ಸಾವಿರಾರು ಟ್ರೇಡರ್‌ಗಳೊಂದಿಗೆ ಸೇರಿ.',
