  'cta.sub': 'ಅನುಕೂಲಕ್ಕಿಂತ ಸ್ವಾತಂತ್ರ್ಯವನ್ನು ಆರಿಸಿಕೊಂಡ ಸಾವಿರಾರು ಟ್ರೇಡರ್‌ಗಳೊಂದಿಗೆ ಸೇರಿ.',
  'cta.boxTitle': 'ನಿಮ್ಮ ಸ್ಟ್ರಾಟಜಿಗಳು ನಿಮ್ಮವೇ ಆಗಿ ಉಳಿಯುತ್ತವೆ. ನಿಮ್ಮ ಸರ್ವೀಸ್‌ಗಳು ನಿಮ್ಮ ಸ್ವಾಮ್ಯದಲ್ಲೇ ಇರುತ್ತವೆ. ಇನ್‌ಫ್ರಾಸ್ಟ್ರಕ್ಚರ್ ಮಾತ್ರ ಓಪನ್ ಆಗಿಯೇ ಇರುತ್ತದೆ.',
