  'priv.zero.body': 'OpenAlgo ಮತ್ತು OpenAlgo ವೆಬ್ ಪೋರ್ಟಲ್ ಯಾವುದೇ ಬಳಕೆದಾರ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ, ಸಂಗ್ರಹಿಸಿಡುವುದಿಲ್ಲ, ರವಾನಿಸುವುದಿಲ್ಲ, ಅಥವಾ ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುವುದಿಲ್ಲ. ಯಾವುದೇ ಅನಲಿಟಿಕ್ಸ್, ಟೆಲಿಮೆಟ್ರಿ, ಟ್ರ್ಯಾಕಿಂಗ್ ಕುಕೀಗಳು, ಬಳಕೆದಾರ ವರ್ತನೆ ಮಾನಿಟರಿಂಗ್, ಅಥವಾ ಯಾವುದೇ ರೀತಿಯ ಡೇಟಾ ಸಂಗ್ರಹಣೆ ಇಲ್ಲ.',
