  'priv.self.title': 'ಸೆಲ್ಫ್-ಹೋಸ್ಟೆಡ್ ಆರ್ಕಿಟೆಕ್ಚರ್',
  'priv.self.intro': 'OpenAlgo ಅನ್ನು ನಿಮ್ಮ ಸ್ವಂತ ಇನ್‌ಫ್ರಾಸ್ಟ್ರಕ್ಚರ್‌ನಲ್ಲಿ ಸೆಲ್ಫ್-ಹೋಸ್ಟ್ ಮಾಡುವ ರೀತಿಯಲ್ಲಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾಗಿದೆ. ಇದರರ್ಥ:',
