  'priv.trans.title': 'ಪಾರದರ್ಶಕತೆ',
  'priv.trans.intro': 'OpenAlgo AGPL-3.0 ಲೈಸೆನ್ಸ್ ಅಡಿಯಲ್ಲಿ ಸಂಪೂರ್ಣವಾಗಿ ಓಪನ್-ಸೋರ್ಸ್ ಆಗಿದೆ. ನೀವು ಹೀಗೆ ಮಾಡಬಹುದು:',
  'priv.trans.i1': 'GitHubನಲ್ಲಿ ಇಡೀ ಕೋಡ್‌ಬೇಸ್ ಅನ್ನು ಆಡಿಟ್ ಮಾಡಿ',
