  'priv.third.note': 'ಗಮನಿಸಿ: OpenAlgo ಆ್ಯಪ್ಲಿಕೇಶನ್ ಸ್ವತಃ, ಸೆಲ್ಫ್-ಹೋಸ್ಟ್ ಮಾಡಿದಾಗ, ಯಾವುದೇ ಥರ್ಡ್-ಪಾರ್ಟಿ ಸೇವೆಗಳನ್ನು ಬಳಸುವುದಿಲ್ಲ.',
  'priv.changes.title': 'ಈ ನೀತಿಗೆ ಬದಲಾವಣೆಗಳು',
  'priv.changes.body': 'ಶೂನ್ಯ ಡೇಟಾ ಸಂಗ್ರಹಣೆಗೆ ನಮ್ಮ ಬದ್ಧತೆ ಶಾಶ್ವತವಾಗಿದೆ. ಈ ನೀತಿಗೆ ಯಾವುದೇ ಅಪ್‌ಡೇಟ್‌ಗಳು ನಮ್ಮ ಗೌಪ್ಯತಾ ನಿಲುವನ್ನು ಸ್ಪಷ್ಟಪಡಿಸುತ್ತವೆ ಅಥವಾ ಬಲಪಡಿಸುತ್ತವೆ, ಎಂದಿಗೂ ದುರ್ಬಲಗೊಳಿಸುವುದಿಲ್ಲ.',
