  'dl.sdkDescPre': 'ಆ್ಯಪ್ಲಿಕೇಶನ್ ಡೆವಲಪ್‌ಮೆಂಟ್‌ಗಾಗಿ ಅಧಿಕೃತ ಕ್ಲೈಂಟ್ ಪ್ಯಾಕೇಜ್‌ಗಳು. ಈ ಆಧಾರದ ಮೇಲೆ ನಿರ್ಮಿಸಲಾಗಿದೆ',
  'dl.sdkDescPost': '- ಸ್ಥಿರ, backward-compatible, ಮತ್ತು production ಬಳಕೆಗೆ ಶಿಫಾರಸು ಮಾಡಲಾಗಿದೆ.',
  'dl.viewDocs': 'ಡಾಕ್ಸ್ ನೋಡಿ',
  'dl.intLabel': 'ಲೈಬ್ರರಿಗಳು & ಪ್ಲಾಟ್‌ಫಾರ್ಮ್ ಇಂಟಿಗ್ರೇಷನ್‌ಗಳು',
  'dl.intDesc': 'ಜನಪ್ರಿಯ ಟ್ರೇಡಿಂಗ್ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗಳಿಗೆ, ಅನಾಲಿಸಿಸ್ ಟೂಲ್‌ಗಳಿಗೆ, ಮತ್ತು ಯೂಸರ್ ಇಂಟರ್‌ಫೇಸ್‌ಗಳಿಗೆ OpenAlgo ಬೆಂಬಲವನ್ನು ವಿಸ್ತರಿಸುವ ಟೂಲ್‌ಗಳು.',
  'dl.docsTitle': 'ಡಾಕ್ಯುಮೆಂಟೇಷನ್ & ಉದಾಹರಣೆಗಳು',
  'dl.docsDesc': 'ಪ್ರತಿ SDK ಮತ್ತು ಇಂಟಿಗ್ರೇಷನ್‌ಗೆ ಇನ್‌ಸ್ಟಾಲೇಷನ್ ಹಂತಗಳು, ಕಾನ್ಫಿಗರೇಷನ್ ಮಾರ್ಗದರ್ಶನ, ಮತ್ತು ಕಾರ್ಯನಿರ್ವಹಿಸುವ ಉದಾಹರಣೆಗಳ ಪ್ರತ್ಯೇಕ ಡಾಕ್ಯುಮೆಂಟೇಷನ್ ಇದೆ.',
  'dl.docsLinkLabel': '{x} ಡಾಕ್ಸ್',
  'dl.philLead': 'ಮಿನಿ FOSS ಯೂನಿವರ್ಸ್ OpenAlgoದ ಕೋರ್ ತತ್ವವನ್ನು ಪ್ರತಿಬಿಂಬಿಸುತ್ತದೆ:',
  'dl.philStrong': 'ಓಪನ್ ಸ್ಟ್ಯಾಂಡರ್ಡ್‌ಗಳು, ಪಾರದರ್ಶಕ ಡಿಸೈನ್, ಮತ್ತು ಟ್ರೇಡರ್‌ಗಳು ನಿಜವಾಗಿ ಕೆಲಸ ಮಾಡುವ ರೀತಿಗೆ ಹೊಂದಿಕೊಳ್ಳುವ ಟೂಲ್‌ಗಳು.',
