  'dl.req1': 'ಚಾಲ್ತಿಯಲ್ಲಿರುವ OpenAlgo ಇನ್‌ಸ್ಟನ್ಸ್ (self-hosted ಅಥವಾ cloud)',
  'dl.req2': 'ನಿಮ್ಮ OpenAlgo ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಿಂದ ಜನರೇಟ್ ಮಾಡಿದ ಮಾನ್ಯ API key',
  'dl.req3': 'ನಿಮ್ಮ OpenAlgo ಇನ್‌ಸ್ಟನ್ಸ್ ಅನ್ನು ಸೂಚಿಸುವ ಸರಿಯಾದ host URL ಕಾನ್ಫಿಗರೇಷನ್',
  'dl.req4': 'OpenAlgo ನಲ್ಲಿ ಕಾನ್ಫಿಗರ್ ಮಾಡಿದ ಸಕ್ರಿಯ ಬ್ರೋಕರ್ ಕನೆಕ್ಷನ್',
  'dl.reqNote': 'ಈ ಟೂಲ್‌ಗಳನ್ನು ಬಳಸುವ ಮೊದಲು OpenAlgo ಚಾಲ್ತಿಯಲ್ಲಿದೆ ಮತ್ತು ಆಕ್ಸೆಸ್ ಮಾಡಬಹುದು ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ. ನಿಮ್ಮ OpenAlgo ಡ್ಯಾಶ್‌ಬೋರ್ಡ್‌ನಲ್ಲಿ Settings → API Key Management ನಿಂದ ನೀವು API key ಗಳನ್ನು ಜನರೇಟ್ ಮಾಡಬಹುದು.',
