  'skill.h1a': 'ನಿಮ್ಮ AI ಗೆ ಕಲಿಸಿ',
  'skill.h1b': 'ಟ್ರೇಡ್ ಮಾಡಲು ಮತ್ತು ನಿರ್ಮಿಸಲು',
  'skill.heroDesc': 'OpenAlgo Skills ನಿಮ್ಮ AI ಅಸಿಸ್ಟಂಟ್‌ಗೆ ಸಿದ್ಧ ಟ್ರೇಡಿಂಗ್ ಜ್ಞಾನವನ್ನು ಸೇರಿಸುತ್ತದೆ - ಚಾರ್ಟ್‌ಗಳು, ಸ್ಕ್ಯಾನರ್‌ಗಳು, ಕಸ್ಟಮ್ ಇಂಡಿಕೇಟರ್‌ಗಳು, ಮತ್ತು ವಾಸ್ತವಿಕ ಬ್ರೋಕರೇಜ್ ವೆಚ್ಚಗಳೊಂದಿಗೆ ಪೂರ್ಣ ಬ್ಯಾಕ್‌ಟೆಸ್ಟ್‌ಗಳು.',
  'skill.heroDesc2': 'ಕೋಡಿಂಗ್ ಅನುಭವದ ಅಗತ್ಯವಿಲ್ಲ. ಸರಳ ಭಾಷೆಯಲ್ಲಿ ನಿಮ್ಮ AI ಗೆ ನಿಮಗೆ ಏನು ಬೇಕೆಂದು ಹೇಳಿ, ಅದು ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
  'skill.heroInstallNote': 'ಇದನ್ನು ನಿಮ್ಮ ಟರ್ಮಿನಲ್‌ನಲ್ಲಿ ಒಮ್ಮೆ ಪೇಸ್ಟ್ ಮಾಡಿ. ನಿಮ್ಮ AI ಟೂಲ್ ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಅದನ್ನು ಪಡೆದುಕೊಳ್ಳುತ್ತದೆ.',
  'skill.ctaSee': 'ನೀವು ಏನು ಮಾಡಬಹುದೆಂದು ನೋಡಿ',
  'skill.ctaDocs': 'ಪೂರ್ಣ ಡಾಕ್ಸ್',
  'skill.whatTitle': 'Skill ಎಂದರೇನು?',
  'skill.whatSub': 'Skill ಅನ್ನು ನಿಮ್ಮ AI ಗಾಗಿ ಒಂದು ಪ್ಲಗ್-ಇನ್ ಎಂದು ಯೋಚಿಸಿ. ಇದನ್ನು ಒಮ್ಮೆ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ ಮತ್ತು ನಿಮ್ಮ AI ಹೊಸ ಸಾಮರ್ಥ್ಯಗಳನ್ನು ಪಡೆದುಕೊಳ್ಳುತ್ತದೆ - ಇಂಡಿಕೇಟರ್ ಚಾರ್ಟ್ ಮಾಡುವುದು, ಷೇರುಗಳನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡುವುದು, ಅಥವಾ ಪೂರ್ಣ ಬ್ಯಾಕ್‌ಟೆಸ್ಟ್ ಚಲಾಯಿಸುವುದು, ಎಲ್ಲವೂ ಒಂದೇ ಸೂಚನೆಯಲ್ಲಿ.',
  'skill.w1t': 'ಮೊದಲ ದಿನವೇ ಸಿದ್ಧ',
  'skill.w1d': 'ಉದ್ದದ ಪ್ರಾಂಪ್ಟ್‌ಗಳಿಲ್ಲ, ಟ್ಯುಟೋರಿಯಲ್‌ಗಳಿಂದ ಕೋಡ್ ಕಾಪಿ-ಪೇಸ್ಟ್ ಮಾಡುವುದಿಲ್ಲ. ಕೇಳಿ ಅಷ್ಟೇ, ನಿಮ್ಮ AI ಗೆ ಈಗಾಗಲೇ ಹೇಗೆಂದು ಗೊತ್ತಿದೆ.',
  'skill.w2t': 'ಪರೀಕ್ಷಿಸಿದ ರೆಸಿಪಿಗಳು',
  'skill.w2d': 'ಪ್ರತಿ skill ಅನುಭವಿ ಟ್ರೇಡರ್‌ಗಳು ಬಳಸುವ ಅದೇ ವಿಶ್ವಾಸಾರ್ಹ, ಬಳಸಲು-ಸಿದ್ಧ ಬಿಲ್ಡಿಂಗ್ ಬ್ಲಾಕ್‌ಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ.',
  'skill.w3t': 'ಸರಳ ಕಮಾಂಡ್‌ಗಳು',
  'skill.w3d': '/backtest ಅಥವಾ /indicator-chart ನಂತಹ ತ್ವರಿತ ಶಾರ್ಟ್‌ಕಟ್‌ಗಳು ಪ್ರತಿ ಕೆಲಸವನ್ನೂ ಪ್ರಾರಂಭಿಸುತ್ತವೆ. ಉಳಿದದ್ದನ್ನು ನಿಮ್ಮ AI ನಿಭಾಯಿಸುತ್ತದೆ.',
  'skill.agentsTitle': 'ನಿಮ್ಮ AI ಟೂಲ್ ಜೊತೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ',
  'skill.agentsSub': 'ನೀವು ಯಾವುದೇ AI ಕೋಡಿಂಗ್ ಆಪ್ ಬಳಸಿದರೂ, Skills ಸರಿಯಾಗಿ ಹೊಂದಿಕೊಳ್ಳುತ್ತವೆ. ಒಂದು-ಸಾಲಿನ ಇನ್‌ಸ್ಟಾಲ್ ಅವುಗಳನ್ನು ಎಲ್ಲಿ ಇಡಬೇಕೆಂದು ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕಂಡುಹಿಡಿಯುತ್ತದೆ.',
  'skill.agentsMore': '+ 30 ಇನ್ನಷ್ಟು',
  'skill.packsTitle': 'ಎರಡು Skill ಪ್ಯಾಕ್‌ಗಳು',
  'skill.packsSub': 'ನಿಮಗೆ ಬೇಕಾದ್ದನ್ನು ಆರಿಸಿ, ಅಥವಾ ಎರಡನ್ನೂ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡಿ. ಎರಡೂ ಉಚಿತ ಮತ್ತು ಓಪನ್ ಸೋರ್ಸ್.',
  'skill.tabIndicators': 'ಇಂಡಿಕೇಟರ್‌ಗಳು ಮತ್ತು ಚಾರ್ಟ್‌ಗಳು',
  'skill.tabBacktesting': 'ಬ್ಯಾಕ್‌ಟೆಸ್ಟಿಂಗ್',
  'skill.indTitle': 'ಇಂಡಿಕೇಟರ್ ಮತ್ತು ಚಾರ್ಟಿಂಗ್ Skills',
  'skill.indDesc': 'ಯಾವುದೇ ಸಿಂಬಲ್‌ನಲ್ಲಿ ಯಾವುದೇ ಇಂಡಿಕೇಟರ್ ಚಾರ್ಟ್ ಮಾಡಿ, ಕಸ್ಟಮ್ ಇಂಡಿಕೇಟರ್‌ಗಳನ್ನು ನಿರ್ಮಿಸಿ, ಸೆಟಪ್‌ಗಳಿಗಾಗಿ ಸ್ಕ್ಯಾನ್ ಮಾಡಿ, ಮತ್ತು ಲೈವ್ ಬೆಲೆಗಳನ್ನು ಸ್ಟ್ರೀಮ್ ಮಾಡಿ - ಎಲ್ಲವೂ ನಿಮ್ಮ AI ಗೆ ಸರಳ-ಭಾಷೆಯ ವಿನಂತಿಗಳಿಂದ ನಡೆಸಲ್ಪಡುತ್ತದೆ.',
