  'skill.ic1t': 'ಮೊದಲ ಬಾರಿಯ ಸೆಟಪ್',
  'skill.ic1d': 'ನಿಮ್ಮ ಯಂತ್ರದಲ್ಲಿ ನಿಮ್ಮ AI ಗೆ ಬೇಕಾದ ಎಲ್ಲವನ್ನೂ ಇನ್‌ಸ್ಟಾಲ್ ಮಾಡುತ್ತದೆ. ಇದನ್ನು ಒಮ್ಮೆ ಚಲಾಯಿಸಿ ಮತ್ತು ನೀವು ಸಿದ್ಧ.',
  'skill.ic2t': 'ಯಾವುದೇ ಇಂಡಿಕೇಟರ್ ಚಾರ್ಟ್ ಮಾಡಿ',
  'skill.ic2d': 'ಯಾವುದೇ ಷೇರು ಅಥವಾ ಸೂಚ್ಯಂಕದಲ್ಲಿ EMA, RSI, Supertrend ಅಥವಾ ಇನ್ನಾವುದೇ ಇಂಡಿಕೇಟರ್ ಕೇಳಿ. ನಿಮಗೆ buy/sell ಮಾರ್ಕರ್‌ಗಳೊಂದಿಗೆ ಶುದ್ಧ ಡಾರ್ಕ್-ಥೀಮ್ ಚಾರ್ಟ್ ಸಿಗುತ್ತದೆ.',
