  'skill.ic3d': 'ಹೊಸ ಇಂಡಿಕೇಟರ್ ಅನ್ನು ಸರಳ ಭಾಷೆಯಲ್ಲಿ ವಿವರಿಸಿ. ನಿಮ್ಮ AI ಕೋಡ್ ಬರೆಯುತ್ತದೆ, ಚಾರ್ಟ್ ಬಿಡಿಸುತ್ತದೆ, ಮತ್ತು ಅದರ ವೇಗವನ್ನು ಪರಿಶೀಲಿಸುತ್ತದೆ.',
  'skill.ic4t': 'ಲೈವ್ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಮಾಡಿ',
  'skill.ic4d': 'ನಿಮ್ಮ ಮೆಚ್ಚಿನ ಇಂಡಿಕೇಟರ್‌ಗಳೊಂದಿಗೆ ಸೂಕ್ತ ವೆಬ್ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್, ಮಾರುಕಟ್ಟೆಯಿಂದ ಲೈವ್ ರಿಫ್ರೆಶ್ ಆಗುತ್ತದೆ.',
  'skill.ic5t': 'ಮಾರುಕಟ್ಟೆಯನ್ನು ಸ್ಕ್ಯಾನ್ ಮಾಡಿ',
