  'skill.btTitle': 'ಬ್ಯಾಕ್‌ಟೆಸ್ಟಿಂಗ್ Skills',
  'skill.btDesc': 'ನೈಜ ಹಿಂದಿನ ಡೇಟಾದ ಮೇಲೆ ಟ್ರೇಡಿಂಗ್ ಐಡಿಯಾಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ. ಭಾರತೀಯ, US ಮತ್ತು ಕ್ರಿಪ್ಟೋ ಮಾರುಕಟ್ಟೆಗಳಿಗೆ ಶುಲ್ಕಗಳು, ತೆರಿಗೆಗಳು ಮತ್ತು ಸ್ಲಿಪೇಜ್ ಈಗಾಗಲೇ ಸೇರಿಸಲಾಗಿದೆ - ಆದ್ದರಿಂದ ಫಲಿತಾಂಶಗಳು ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ನೀವು ನಿಜವಾಗಿ ನೋಡುವುದನ್ನು ಪ್ರತಿಬಿಂಬಿಸುತ್ತವೆ.',
  'skill.bc1t': 'ಮೊದಲ ಬಾರಿಯ ಸೆಟಪ್',
  'skill.bc1d': 'ನಿಮ್ಮ ಯಂತ್ರದಲ್ಲಿ ಬ್ಯಾಕ್‌ಟೆಸ್ಟ್‌ಗಳನ್ನು ಚಲಾಯಿಸಲು ಬೇಕಾದ ಎಲ್ಲವನ್ನೂ ಸಿದ್ಧಪಡಿಸುತ್ತದೆ. ಒಮ್ಮೆ ಚಲಾಯಿಸಿ.',
  'skill.bc2t': 'ಸ್ಟ್ರಾಟಜಿಯನ್ನು ಬ್ಯಾಕ್‌ಟೆಸ್ಟ್ ಮಾಡಿ',
  'skill.bc2d': 'ವಾಸ್ತವಿಕ ಬ್ರೋಕರೇಜ್ ಮತ್ತು ತೆರಿಗೆಗಳೊಂದಿಗೆ ಹಿಂದಿನ ಡೇಟಾದ ಮೇಲೆ ಯಾವುದೇ ಸ್ಟ್ರಾಟಜಿಯನ್ನು ಚಲಾಯಿಸಿ. ಸರಳ ಭಾಷೆಯಲ್ಲಿ ಪೂರ್ಣ ವರದಿ, ಜೊತೆಗೆ ಪ್ರೊ-ಗ್ರೇಡ್ PDF-ಶೈಲಿಯ ಟಿಯರ್‌ಶೀಟ್ ಪಡೆಯಿರಿ.',
  'skill.bc3t': 'ಅತ್ಯುತ್ತಮ ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಹುಡುಕಿ',
  'skill.bc3d': 'ಸ್ಟ್ರಾಟಜಿಯ ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಅನೇಕ ಸಂಯೋಜನೆಗಳನ್ನು ಪರೀಕ್ಷಿಸಿ ಮತ್ತು ದೃಶ್ಯಾತ್ಮಕ heatmap ನಲ್ಲಿ ಅತ್ಯುತ್ತಮವಾದವುಗಳನ್ನು ಹೈಲೈಟ್ ಮಾಡಿ.',
  'skill.bc4t': 'ತ್ವರಿತ ಸ್ಯಾನಿಟಿ ಚೆಕ್',
  'skill.bc4d': 'ಸ್ಟ್ರಾಟಜಿಯ ರಿಟರ್ನ್, ಡ್ರಾಡೌನ್, ಮತ್ತು ಅದು ಸೂಚ್ಯಂಕಕ್ಕೆ ಹೋಲಿಸಿದರೆ ಹೇಗಿದೆ ಎಂಬುದರ ತ್ವರಿತ ಓದು - ಯಾವುದೇ ಫೈಲ್‌ಗಳು ರಚಿಸಲ್ಪಡುವುದಿಲ್ಲ.',
