  'mcp.flow4d': 'ಆರ್ಡರ್ ನಿಮ್ಮ ಬ್ರೋಕರ್‌ಗೆ ಹೋಗಿ ಎಕ್ಸ್‌ಚೇಂಜ್ ತಲುಪುತ್ತದೆ - ಎಂದಿನಂತೆಯೇ.',
