  'mcp.clients.sub': 'ನೀವು ಈಗಾಗಲೇ ಇಷ್ಟಪಡುವ ಚಾಟ್ ಆ್ಯಪ್ ಬಳಸಿ. ಬದಲಿಸುವ ಅಥವಾ ಹೊಸ ಟೂಲ್ ಕಲಿಯುವ ಅಗತ್ಯವಿಲ್ಲ.',
  'mcp.client1d': 'Anthropic ನ ಮೂಲ MCP-ಫಸ್ಟ್ ಡೆಸ್ಕ್‌ಟಾಪ್ ಆ್ಯಪ್.',
  'mcp.client2d': 'ನಿಮ್ಮ ಎಡಿಟರ್‌ನಿಂದಲೇ ಟ್ರೇಡ್ ಮಾಡಿ.',
  'mcp.client3d': 'Codeium ನಿಂದ MCP-ಸಕ್ರಿಯಗೊಳಿಸಿದ AI IDE.',
  'mcp.client4d': 'MCP ಬೆಂಬಲಿತವಾಗಿರುವ ಎಲ್ಲೆಡೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ.',
  'mcp.quickstart.title': 'ಪ್ರಾರಂಭಿಸುವುದು',
  'mcp.quickstart.sub': 'ಮೂರು ಬೇಗನೆ ಹಂತಗಳು - ಒಂದು ಬಾರಿಯ ಸೆಟಪ್, ಮತ್ತು ನೀವು ನಿಮ್ಮ ಟ್ರೇಡಿಂಗ್ ಖಾತೆಯೊಂದಿಗೆ ಮಾತನಾಡುತ್ತೀರಿ.',
  'mcp.qs1.title': 'ನಿಮ್ಮ ಬ್ರೋಕರ್ ಜೊತೆ OpenAlgo ಅನ್ನು ರನ್ ಮಾಡಿ',
  'mcp.qs1.b1': 'OpenAlgo ನಿಮ್ಮ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲಿ ರನ್ ಆಗುತ್ತಿದೆ ಮತ್ತು ನಿಮ್ಮ ಬ್ರೋಕರ್ ಲಾಗಿನ್ ಆಗಿದೆ ಎಂದು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಿ.',
  'mcp.qs1.b2a': 'OpenAlgo ತೆರೆಯಿರಿ, ',
  'mcp.qs1.b2b': 'Settings → API Keys',
  'mcp.qs1.b2c': ' ಗೆ ಹೋಗಿ, ಮತ್ತು ನಿಮ್ಮ key ಕಾಪಿ ಮಾಡಿ. ಅದನ್ನು ಸಿದ್ಧವಾಗಿಟ್ಟುಕೊಳ್ಳಿ.',
  'mcp.qs1.b3': 'GitHub ನಿಂದ MCP ಸೆಟಪ್ ಫೈಲ್‌ಗಳನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿ. ಪೂರ್ಣ ಸೆಟಪ್ ಗೈಡ್ ಇದನ್ನು ಒಂದು ನಿಮಿಷಕ್ಕಿಂತ ಕಡಿಮೆ ಸಮಯದಲ್ಲಿ ವಿವರಿಸುತ್ತದೆ.',
  'mcp.qs1.cta': 'OpenAlgo ಗೆ ಹೊಸಬರೇ? ಇಲ್ಲಿಂದ ಪ್ರಾರಂಭಿಸಿ',
  'mcp.qs2.title': 'ನಿಮ್ಮ AI ಗೆ OpenAlgo ಬಗ್ಗೆ ಹೇಳಿ',
  'mcp.qs2.desc': 'ಕೆಳಗೆ ನಿಮ್ಮ ಆಪರೇಟಿಂಗ್ ಸಿಸ್ಟಂ ಆಯ್ಕೆಮಾಡಿ, ಸೆಟ್ಟಿಂಗ್‌ಗಳನ್ನು ಕಾಪಿ ಮಾಡಿ, ಮತ್ತು ಅವುಗಳನ್ನು ನಿಮ್ಮ AI ಆ್ಯಪ್‌ನ config ಫೈಲ್‌ಗೆ ಪೇಸ್ಟ್ ಮಾಡಿ. ಪಾತ್‌ಗಳು ಮತ್ತು API key ಅನ್ನು ನಿಮ್ಮದೇ ಆದವುಗಳಿಂದ ಬದಲಾಯಿಸಿ.',
  'mcp.qs2.pathsLabel': 'ಸೆಟ್ಟಿಂಗ್ಸ್ ಫೈಲ್ ಎಲ್ಲಿದೆ:',
  'mcp.qs2.helpPre': 'ನಿಖರ ಪಾತ್‌ಗಳ ಬಗ್ಗೆ ಸಹಾಯ ಬೇಕೇ?',
  'mcp.qs2.helpLink': 'ವಿವರವಾದ ಸೆಟಪ್ ಗೈಡ್ ನೋಡಿ',
  'mcp.qs3.title': 'ನಿಮ್ಮ AI ಆ್ಯಪ್ ಮರುಪ್ರಾರಂಭಿಸಿ ಮತ್ತು ಟ್ರೇಡಿಂಗ್ ಆರಂಭಿಸಿ',
  'mcp.qs3.desc': 'Claude Desktop, Cursor, ಅಥವಾ Windsurf ಅನ್ನು ಮುಚ್ಚಿ ಮತ್ತೆ ತೆರೆಯಿರಿ. OpenAlgo ಸ್ವಯಂಚಾಲಿತವಾಗಿ ಕನೆಕ್ಟ್ ಆಗುತ್ತದೆ. ಮೊದಲು ಸರಳವಾದದ್ದನ್ನು ಕೇಳಿ ನೋಡಿ:',
  'mcp.qs3.you': 'ನೀವು >',
  'mcp.qs3.prompt': 'ನನ್ನ ಫಂಡ್ಸ್ ಮತ್ತು ಓಪನ್ ಪೊಸಿಷನ್‌ಗಳನ್ನು ತೋರಿಸಿ',
  'mcp.exch.title': 'ನೀವು ಟ್ರೇಡ್ ಮಾಡಬಹುದಾದ ಎಕ್ಸ್‌ಚೇಂಜ್‌ಗಳು',
  'mcp.exch.sub': 'ನಿಮ್ಮ ಬ್ರೋಕರ್ OpenAlgo ಮೂಲಕ ಟ್ರೇಡ್ ಮಾಡಲು ಅನುಮತಿಸುವ ಯಾವುದನ್ನಾದರೂ, ನೀವು ಚಾಟ್ ಮೂಲಕ ಟ್ರೇಡ್ ಮಾಡಬಹುದು.',
  'mcp.exch.nse': 'NSE ಎಕ್ವಿಟಿ',
  'mcp.exch.nfo': 'NSE F&O',
  'mcp.exch.cds': 'NSE ಕರೆನ್ಸಿ',
  'mcp.exch.bse': 'BSE ಎಕ್ವಿಟಿ',
  'mcp.exch.bfo': 'BSE F&O',
  'mcp.exch.bcd': 'BSE ಕರೆನ್ಸಿ',
  'mcp.exch.mcx': 'ಕಮಾಡಿಟಿ',
  'mcp.exch.ncdex': 'NCDEX',
  'mcp.sec.title': 'ತಿಳಿದುಕೊಳ್ಳಬೇಕಾದ ಕೆಲವು ಸಂಗತಿಗಳು',
  'mcp.sec.b1': 'ಎಲ್ಲವೂ ನಿಮ್ಮ ಸ್ವಂತ ಕಂಪ್ಯೂಟರ್‌ನಲ್ಲೇ ರನ್ ಆಗುತ್ತದೆ. ನಿಮ್ಮ ಆರ್ಡರ್‌ಗಳು ಮತ್ತು ಖಾತೆ ಮಾಹಿತಿ ನಿಮ್ಮ ಯಂತ್ರವನ್ನು ಎಂದಿಗೂ ಬಿಟ್ಟು ಹೋಗುವುದಿಲ್ಲ.',
  'mcp.sec.b2': 'ನಿಮ್ಮ API key ಸ್ಥಳೀಯವಾಗಿಯೇ ಉಳಿಯುತ್ತದೆ - ಅದನ್ನು ಎಂದಿಗೂ ಅಪ್‌ಲೋಡ್ ಅಥವಾ ಶೇರ್ ಮಾಡಲಾಗುವುದಿಲ್ಲ.',
  'mcp.sec.b3': 'AI ಕೆಲವೊಮ್ಮೆ ತಪ್ಪುಗಳನ್ನು ಮಾಡಬಹುದು. ಒಪ್ಪಿಗೆ ನೀಡುವ ಮೊದಲು ಅದು ಏನು ಮಾಡಲಿದೆ ಎಂಬುದನ್ನು ಯಾವಾಗಲೂ ಓದಿ - ವಿಶೇಷವಾಗಿ ಆರ್ಡರ್‌ಗಳಿಗೆ.',
  'mcp.cta.title': 'ಕ್ಲಿಕ್‌ಗಳನ್ನು ನಿಮ್ಮ AI ನಿಭಾಯಿಸಲಿ.',
  'mcp.cta.sub': 'ಒಮ್ಮೆ ಸೆಟಪ್ ಮಾಡಿ. ನಂತರ, ಮಾತನಾಡಿ ಅಷ್ಟೇ. ನಿಮ್ಮ ಬ್ರೋಕರ್, ನಿಮ್ಮ ಸ್ಟ್ರಾಟಜಿಗಳು, ಸಂಪೂರ್ಣವಾಗಿ ನಿಮ್ಮ ನಿಯಂತ್ರಣದಲ್ಲಿ.',
