  'wab.badgeOpenSource': 'ಓಪನ್ ಸೋರ್ಸ್',
  'wab.heroTag': 'ಒಂದು ಹಗುರ WhatsApp HTTP ಬ್ರಿಡ್ಜ್.',
  'wab.heroDesc': 'CLI ಮೂಲಕ ನಿಮ್ಮ WhatsApp ಲಿಂಕ್ ಮಾಡಿ, ನಂತರ ಸರಳ REST API ಮೂಲಕ ಮೆಸೇಜ್‌ಗಳನ್ನು ಕಳುಹಿಸಿ. ಟೆಕ್ಸ್ಟ್, ಇಮೇಜ್, ವಿಡಿಯೋ, ಆಡಿಯೋ, ಡಾಕ್ಯುಮೆಂಟ್‌ಗಳನ್ನು ಬೆಂಬಲಿಸುತ್ತದೆ - ವ್ಯಕ್ತಿಗಳಿಗೆ, ಗ್ರೂಪ್‌ಗಳಿಗೆ, ಮತ್ತು ಚಾನಲ್‌ಗಳಿಗೆ.',
