  'wab.howCaption': 'ನಿಮ್ಮ ಆ್ಯಪ್ WABridge ಗೆ HTTP ರಿಕ್ವೆಸ್ಟ್‌ಗಳನ್ನು ಕಳುಹಿಸುತ್ತದೆ, ಅದು ಅವುಗಳನ್ನು WhatsApp ಗೆ ತಲುಪಿಸುತ್ತದೆ.',
  'wab.f1t': 'ಸರಳ REST API',
