  'wab.f3t': 'ಗ್ರೂಪ್‌ಗಳು ಮತ್ತು ಚಾನಲ್‌ಗಳು',
  'wab.f3d': 'ವ್ಯಕ್ತಿಗಳಿಗೆ, ಗ್ರೂಪ್‌ಗಳಿಗೆ, ಮತ್ತು ಚಾನಲ್‌ಗಳಿಗೆ ಕಳುಹಿಸಿ. ಗ್ರೂಪ್‌ಗಳನ್ನು ಅವುಗಳ JID ಗಳ ಸಹಿತ ಪ್ರೋಗ್ರಾಮ್ಯಾಟಿಕಲಿ ಪಟ್ಟಿ ಮಾಡಿ.',
