  'gs.oss.o3': 'ಶಾಶ್ವತವಾಗಿ ಉಚಿತ. ಸಬ್‌ಸ್ಕ್ರಿಪ್ಷನ್‌ಗಳಿಲ್ಲ, ಶುಲ್ಕಗಳಿಲ್ಲ',
  'gs.oss.o4': 'ಕಮ್ಯುನಿಟಿ-ಚಾಲಿತ, ಪಾರದರ್ಶಕ ಡೆವಲಪ್‌ಮೆಂಟ್',
  'gs.how.title': 'OpenAlgo ಹೇಗೆ ಕೆಲಸ ಮಾಡುತ್ತದೆ?',
  'gs.how.sub': 'OpenAlgo ನಿಮ್ಮ ಟ್ರೇಡಿಂಗ್ ಐಡಿಯಾಗಳು ಮತ್ತು ನಿಮ್ಮ ಬ್ರೋಕರ್ ನಡುವೆ ಇರುತ್ತದೆ.',
  'gs.how.step1': 'ನಿಮ್ಮ ಸ್ಟ್ರಾಟಜಿ',
