  'gs.how.step3': 'ಬ್ರೋಕರ್ ಸರ್ವರ್',
  'gs.how.flowLabel': 'ಸಿಗ್ನಲ್ ಫ್ಲೋ:',
  'gs.how.flowText': 'ನಿಮ್ಮ ಸ್ಟ್ರಾಟಜಿ ಸಿಗ್ನಲ್ ಉತ್ಪಾದಿಸುತ್ತದೆ → OpenAlgo ಅದನ್ನು ತನ್ನ API ಮೂಲಕ ಸ್ವೀಕರಿಸುತ್ತದೆ → OpenAlgo ಅದನ್ನು ಬ್ರೋಕರ್ ಆರ್ಡರ್ ಆಗಿ ಪರಿವರ್ತಿಸುತ್ತದೆ → ಬ್ರೋಕರ್ ನಿಮ್ಮ ಖಾತೆಯಲ್ಲಿ ಟ್ರೇಡ್ ಎಕ್ಸಿಕ್ಯೂಟ್ ಮಾಡುತ್ತದೆ',
  'gs.how.routineTitle': 'ದೈನಂದಿನ ರೂಟೀನ್',
  'gs.how.routineDesc': 'ಪ್ರತಿ ರಾತ್ರಿ ಬ್ರೋಕರ್ ಆಥೆಂಟಿಕೇಶನ್ ಟೋಕನ್‌ಗಳು ಅವಧಿ ಮುಗಿಯುವುದರಿಂದ (SEBI ನಿಯಮ), OpenAlgo ಗೆ ದೈನಂದಿನ ಲಾಗಿನ್ ಅಗತ್ಯವಿದೆ. ಸಾಮಾನ್ಯ ದೈನಂದಿನ ಫ್ಲೋ ಇಲ್ಲಿದೆ:',
  'gs.how.r1t': '3:00 AM',
