  'gs.how.r2t': '8:00 ರಿಂದ 9:00 AM',
  'gs.how.r2e': 'OpenAlgo ಗೆ ಲಾಗಿನ್ ಮಾಡಿ, ಬ್ರೋಕರ್ ಜೊತೆ ಆಥೆಂಟಿಕೇಟ್ ಆಗುತ್ತದೆ',
