  'gs.how.r5t': '3:30 PM',
  'gs.how.r5e': 'ಮಾರುಕಟ್ಟೆ ಮುಚ್ಚುತ್ತದೆ. ಸ್ಟ್ರಾಟಜಿಗಳು ನಿಲ್ಲುತ್ತವೆ',
  'gs.how.whyLabel': '8 AM ನಂತರ ಏಕೆ?',
  'gs.how.whyText': 'ಬ್ರೋಕರ್‌ಗಳು ಮುಂಜಾನೆ ತಮ್ಮ ಮಾಸ್ಟರ್ ಕಾಂಟ್ರಾಕ್ಟ್‌ಗಳನ್ನು (ಸಿಂಬಲ್ ಲಿಸ್ಟ್‌ಗಳು) ಅಪ್‌ಡೇಟ್ ಮಾಡುತ್ತಾರೆ. 8 AM ನಂತರ ಲಾಗಿನ್ ಮಾಡುವುದರಿಂದ ನಿಮಗೆ ಇತ್ತೀಚಿನ ಸಿಂಬಲ್‌ಗಳು ಸಿಗುತ್ತವೆ ಎಂದು ಖಚಿತಪಡಿಸುತ್ತದೆ, ಇದು ವಾರದ ಎಕ್ಸ್‌ಪೈರಿಗಳಿರುವ ಆಪ್ಷನ್ ಟ್ರೇಡರ್‌ಗಳಿಗೆ ವಿಶೇಷವಾಗಿ ಮುಖ್ಯ.',
  'gs.auth.title': 'ಆಥೆಂಟಿಕೇಶನ್ & ಸೆಕ್ಯುರಿಟಿ',
  'gs.auth.sub': 'OpenAlgo ನಿಮ್ಮ ಬ್ರೋಕರ್‌ಗೆ ಸುರಕ್ಷಿತವಾಗಿ ಹೇಗೆ ಸಂಪರ್ಕಿಸುತ್ತದೆ.',
  'gs.auth.tokenTitle': 'ಆಥೆಂಟಿಕೇಶನ್ ಟೋಕನ್',
  'gs.auth.tokenP1': 'ನೀವು ಲಾಗಿನ್ ಮಾಡಿದಾಗ, ಬ್ರೋಕರ್ ಒಂದು',
  'gs.auth.tokenStrong': 'ಆಥೆಂಟಿಕೇಶನ್ ಟೋಕನ್',
  'gs.auth.tokenP2': 'ಕಳುಹಿಸುತ್ತಾರೆ. ಇದನ್ನು ನಿಮ್ಮ ಮನೆಗೆ ಒಂದು ತಾತ್ಕಾಲಿಕ ಕೀ ಎಂದು ಭಾವಿಸಿ. ಈ ಟೋಕನ್ ~24 ಗಂಟೆಗಳ ಕಾಲ ಮಾನ್ಯವಾಗಿರುತ್ತದೆ ಮತ್ತು ಆರ್ಡರ್ ಇಡುವುದು, ಫಂಡ್ಸ್ ಪರಿಶೀಲಿಸುವುದು, ಮಾರುಕಟ್ಟೆ ಡೇಟಾ ಪ್ರವೇಶಿಸುವುದು ಮುಂತಾದ ಎಲ್ಲಾ ಕಾರ್ಯಾಚರಣೆಗಳಿಗೆ ಬಳಸಲಾಗುತ್ತದೆ. ಇದನ್ನು ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿ ನಿಮ್ಮ ಲೋಕಲ್ ಡೇಟಾಬೇಸ್‌ನಲ್ಲಿ ಸಂಗ್ರಹಿಸಲಾಗುತ್ತದೆ. ಇದನ್ನು ಯಾರೂ ನೋಡಲಾಗುವುದಿಲ್ಲ.',
