  'gs.auth.k1b': 'ಫೈಲ್‌ನಲ್ಲಿ ಕಾನ್ಫಿಗರ್ ಮಾಡಲಾಗುತ್ತದೆ. ಅವುಗಳನ್ನು ಖಾಸಗಿಯಾಗಿ ಇರಿಸಿ. ಎಂದಿಗೂ ಹಂಚಿಕೊಳ್ಳಬೇಡಿ.',
  'gs.auth.k2t': 'OpenAlgo API ಕೀ',
  'gs.auth.k2d': 'OpenAlgo ಒಳಗೇ ಜನರೇಟ್ ಆಗುತ್ತದೆ. ಬಾಹ್ಯ ಪ್ಲಾಟ್‌ಫಾರ್ಮ್‌ಗಳಿಂದ (TradingView, Python, ಇತ್ಯಾದಿ) ಆರ್ಡರ್‌ಗಳನ್ನು ಕಳುಹಿಸಲು ಬಳಸಲಾಗುತ್ತದೆ. ಬಹಿರಂಗವಾದರೆ ಯಾವಾಗ ಬೇಕಾದರೂ ಮರುಜನರೇಟ್ ಮಾಡಬಹುದು.',
  'gs.auth.ipDesc': 'SEBI ನಿಯಮಗಳ ಪ್ರಕಾರ ನಿಮ್ಮ ಟ್ರೇಡಿಂಗ್ ಆರ್ಡರ್‌ಗಳು ಸ್ಥಿರ (ಸ್ಟ್ಯಾಟಿಕ್) IP ವಿಳಾಸದಿಂದ ಬರಬೇಕು. ನಿಮ್ಮ ಬ್ರೋಕರ್‌ನ ಡೆವಲಪರ್ ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಪ್ರೈಮರಿ ಮತ್ತು ಸೆಕೆಂಡರಿ IP ಅನ್ನು ನೋಂದಾಯಿಸಬಹುದು. IP ಗಳನ್ನು ವಾರಕ್ಕೊಮ್ಮೆ ಮಾತ್ರ ಬದಲಾಯಿಸಬಹುದು.',
  'gs.auth.ipHow1': 'ನಿಮ್ಮ ISP ಅನ್ನು ಸಂಪರ್ಕಿಸಿ ಸ್ಟ್ಯಾಟಿಕ್ IP ಕೋರಿ. VPS/ಕ್ಲೌಡ್‌ನಲ್ಲಿ ಹೋಸ್ಟ್ ಮಾಡುತ್ತಿದ್ದರೆ, ಸಾಮಾನ್ಯವಾಗಿ ಸ್ಟ್ಯಾಟಿಕ್ IP ಗಳನ್ನು ಡೀಫಾಲ್ಟ್ ಆಗಿ ಒದಗಿಸಲಾಗುತ್ತದೆ. ನಿಮ್ಮ ಪ್ರಸ್ತುತ IP ಅನ್ನು ಇಲ್ಲಿ ಪರಿಶೀಲಿಸಿ',
  'gs.auth.ipHow2': '. ನಮ್ಮ ಸಂಪೂರ್ಣ',
  'gs.auth.ipHow3': 'ಅನ್ನು ಹಂತ ಹಂತದ ಸೂಚನೆಗಳಿಗಾಗಿ ಓದಿ.',
