  'gs.eco.n9': 'Chrome ಪ್ಲಗಿನ್',
  'gs.eco.d9': 'ಬ್ರೌಸರ್ ಎಕ್ಸ್‌ಟೆನ್ಶನ್',
  'gs.eco.outro': 'ಎಲ್ಲವೂ ಓಪನ್ ಸೋರ್ಸ್. ಎಲ್ಲಾ ಪ್ರಾಜೆಕ್ಟ್‌ಗಳನ್ನು ಇಲ್ಲಿ ಎಕ್ಸ್‌ಪ್ಲೋರ್ ಮಾಡಿ',
  'gs.cta.title': 'ಪ್ರಾರಂಭಿಸಲು ಸಿದ್ಧರಿದ್ದೀರಾ?',
